<?php
namespace AmazingPlugins\Security\Tests\Unit\Network;
use AmazingPlugins\Security\Network\{NetworkSettingsService,NetworkObservation};
use AmazingPlugins\Security\Tests\Unit\Digest\MemoryOptions;
use PHPUnit\Framework\TestCase;
final class SettingsObservationTest extends TestCase {
 public function test_self_lockout_canonical_rules_changed_target_and_recovery():void{$o=new MemoryOptions();$s=new NetworkSettingsService($o);$fp=$s->fingerprint();self::assertSame('self-lockout',$s->apply($fp,'block',['192.0.2.0/24'],['*'],'192.0.2.1'));self::assertSame('self-lockout',$s->apply($fp,'block',['::/0'],['*'],'bad'));self::assertSame('saved',$s->apply($fp,'observe',['192.0.2.123/24','2001:db8::1/32'],['POST'],'192.0.2.1'));self::assertSame(['192.0.2.0/24','2001:db8::/32'],$s->status()['cidrs']);self::assertSame('changed',$s->apply($fp,'block',[],['*'],'192.0.2.1'));self::assertSame('unsupported',$s->apply($s->fingerprint(),'block',['::ffff:192.0.2.1','192.0.2.1'],['*'],'192.0.3.1'));self::assertSame('saved',$s->apply($s->fingerprint(),'block',['192.0.2.0/24'],['GET'],'192.0.3.1'));$o->values['amsec_network_policy']='corrupt';self::assertSame('invalid',$s->apply($s->fingerprint(),'off',[],['*'],'bad'));self::assertTrue($s->disable());self::assertSame('off',$s->status()['mode']);}
 public function test_failed_write_does_not_claim_setting_or_observation():void{$o=new MemoryOptions();$s=new NetworkSettingsService($o);$o->failNetworkWrites=true;self::assertSame('failed',$s->apply($s->fingerprint(),'observe',[],['*'],'bad'));self::assertArrayNotHasKey('amsec_network_policy',$o->values);$log=new NetworkObservation($o);self::assertFalse($log->record(str_repeat('a',32),1000));self::assertArrayNotHasKey('amsec_network_observation',$o->values);}
 public function test_redacted_bounded_revision_observations_and_corruption():void{$o=new MemoryOptions();$log=new NetworkObservation($o);$a=str_repeat('a',32);$b=str_repeat('b',32);self::assertTrue($log->record($a,1000));self::assertTrue($log->record($a,1001));self::assertSame(2,$log->status()['count']);self::assertFalse($log->record($a,999));self::assertTrue($log->record($b,1002));self::assertSame(1,$log->status()['count']);$s=$log->status();$s['count']=1000000;$o->values['amsec_network_observation']=json_encode($s);self::assertTrue($log->record($b,1003));self::assertSame(1000000,$log->status()['count']);$o->values['amsec_network_observation']='bad';self::assertSame(['invalid'=>true],$log->status());self::assertFalse($log->record($b,1004));}
}
